mapper.select:
SELECT *
FROM wizardn.tAthFunctn

    AND RoleUid = #{pRoleUid}
    AND MenuCode = #{pMenuCode}
    AND FunctnUri = #{pFunctnUri}

SELECT COUNT(*) > 0
FROM wizardn.tAthFunctn f
INNER JOIN wizardn.tAthMngr m ON f.RoleUid = m.RoleUid
WHERE f.FunctnUri = #{pFunctnUri}
AND m.LoginId = #{pLoginId}

SELECT *
FROM wizardn.tAthFunctn
WHERE RoleUid = #{roleUid}
AND MenuCode = #{menuCode}
AND FunctnUri = #{functnUri}

mapper.update:
UPDATE wizardn.tAthFunctn SET
    FunctnDesc = #{functnDesc}, State = #{state}, Remark = #{remark},
    ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE RoleUid = #{roleUid}
AND MenuCode = #{menuCode}
AND FunctnUri = #{functnUri}

mapper.delete:
DELETE FROM wizardn.tAthFunctn
WHERE RoleUid = #{roleUid}
AND MenuCode = #{menuCode}
AND FunctnUri = #{functnUri}
